// src/components/Dashboard.jsx
import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import apiService from '../services/apiService';
import TaskModal from './TaskModal';
import './dashboard.css';

const Dashboard = () => {
  const navigate = useNavigate();
  const [tasks, setTasks] = useState([]);
  const [filteredTasks, setFilteredTasks] = useState([]);
  const [currentFilter, setCurrentFilter] = useState('all');
  const [loading, setLoading] = useState(true);
  const [showTaskModal, setShowTaskModal] = useState(false);
  const [editingTask, setEditingTask] = useState(null);
  const [sidebarOpen, setSidebarOpen] = useState(false);
  const [theme, setTheme] = useState('dark');

  useEffect(() => {
    if (!apiService.isAuthenticated()) {
      navigate('/login');
      return;
    }
    loadTasks();
  }, [navigate]);

  useEffect(() => {
    filterTasks();
  }, [tasks, currentFilter]);

  const loadTasks = async () => {
    setLoading(true);
    try {
      const result = await apiService.getTasks();
      if (result.success) {
        setTasks(result.data.data || []);
      } else {
        console.error('Failed to load tasks:', result.error);
        if (result.error && result.error.includes('token')) {
          handleLogout();
        }
      }
    } catch (error) {
      console.error('Error loading tasks:', error);
    } finally {
      setLoading(false);
    }
  };

  const filterTasks = () => {
    let filtered = [...tasks];
    switch (currentFilter) {
      case 'today':
        const today = new Date().toDateString();
        filtered = tasks.filter(task => {
          const taskDate = new Date(task.date_time).toDateString();
          return taskDate === today;
        });
        break;
      case 'pending':
        filtered = tasks.filter(task => task.status !== 'Completed');
        break;
      case 'completed':
        filtered = tasks.filter(task => task.status === 'Completed');
        break;
      case 'advance':
        const tomorrow = new Date();
        tomorrow.setDate(tomorrow.getDate() + 1);
        filtered = tasks.filter(task => {
          if (task.date_time) {
            const taskDate = new Date(task.date_time);
            return taskDate >= tomorrow;
          }
          return false;
        });
        break;
      default:
        filtered = tasks;
    }
    setFilteredTasks(filtered);
  };

  const handleAddTask = () => {
    setEditingTask(null);
    setShowTaskModal(true);
  };

  const handleEditTask = (task) => {
    setEditingTask(task);
    setShowTaskModal(true);
  };

  const handleDeleteTask = async (taskId) => {
    if (!window.confirm('Are you sure you want to delete this task?')) return;
    try {
      const result = await apiService.deleteTask(taskId);
      if (result.success) {
        setTasks(prev => prev.filter(task => task.id !== taskId));
      } else {
        alert('Failed to delete task');
      }
    } catch (error) {
      console.error('Error deleting task:', error);
      alert('Error deleting task');
    }
  };

  const handleTaskSaved = (savedTask) => {
    if (editingTask) {
      setTasks(prev => prev.map(task => task.id === savedTask.id ? savedTask : task));
    } else {
      setTasks(prev => [...prev, savedTask]);
    }
    setShowTaskModal(false);
  };

  const handleLogout = () => {
    apiService.logout();
    navigate('/login');
  };

  const toggleTheme = () => {
    const newTheme = theme === 'dark' ? 'light' : 'dark';
    setTheme(newTheme);
    document.body.setAttribute('data-theme', newTheme);
  };

  const formatDate = (dateString) => {
    if (!dateString) return 'No date';
    return new Date(dateString).toLocaleDateString();
  };

  if (loading) {
    return (
      <div className="loading-container">
        <div className="spinner-border text-primary" role="status">
          <span className="visually-hidden">Loading...</span>
        </div>
      </div>
    );
  }

  return (
    <div className="dashboard" data-theme={theme}>
      {/* Navbar */}
      <nav className="navbar">
        <div className="navbar-left">
          <button 
            className={`menu-btn ${sidebarOpen ? 'open' : ''}`}
            onClick={() => setSidebarOpen(!sidebarOpen)}
          >
            <span className="menu-icon">{sidebarOpen ? '✕' : '☰'}</span>
          </button>
          <div className="logo">AI Task Manager</div>
        </div>
        <div className="navbar-right">
          <button className="theme-toggle" onClick={toggleTheme}>
            {theme === 'dark' ? '🌙 Dark' : '☀️ Light'}
          </button>
          <div className="user-avatar" onClick={handleLogout} title="Logout">
            U
          </div>
        </div>
      </nav>

      {/* Sidebar */}
      <aside className={`sidebar ${sidebarOpen ? 'open' : ''}`}>
        <div className="sidebar-header">
          <div className="sidebar-title">Navigation</div>
          <div className="sidebar-subtitle">Manage your tasks</div>
        </div>
        <nav className="sidebar-nav">
          <button className="nav-item active">
            <span className="nav-icon">📋</span>
            Tasks
          </button>
          <button className="nav-item" onClick={() => navigate('/change-password')}>
            <span className="nav-icon">🔒</span>
            Change Password
          </button>
          <button className="nav-item" onClick={handleLogout}>
            <span className="nav-icon">🚪</span>
            Logout
          </button>
        </nav>
      </aside>

      <div 
        className={`sidebar-overlay ${sidebarOpen ? 'show' : ''}`}
        onClick={() => setSidebarOpen(false)}
      ></div>

      {/* Main Content */}
      <main className={`main-content ${sidebarOpen ? 'shifted' : ''}`}>
        <div className="content-header">
          <h1 className="page-title">Tasks</h1>
          <button className="add-task-btn" onClick={handleAddTask}>+ Add Task</button>
        </div>

        {/* Filters */}
        <div className="task-filters">
          <button 
            className={`filter-btn ${currentFilter === 'all' ? 'active' : ''}`}
            onClick={() => setCurrentFilter('all')}
          >
            All Tasks
          </button>
          <button 
            className={`filter-btn ${currentFilter === 'today' ? 'active' : ''}`}
            onClick={() => setCurrentFilter('today')}
          >
            Today
          </button>
          <button 
            className={`filter-btn ${currentFilter === 'advance' ? 'active' : ''}`}
            onClick={() => setCurrentFilter('advance')}
          >
            Advance
          </button>
          <button 
            className={`filter-btn ${currentFilter === 'pending' ? 'active' : ''}`}
            onClick={() => setCurrentFilter('pending')}
          >
            Pending
          </button>
          <button 
            className={`filter-btn ${currentFilter === 'completed' ? 'active' : ''}`}
            onClick={() => setCurrentFilter('completed')}
          >
            Completed
          </button>
        </div>

        {/* Task List */}
        <div className="task-list">
          {filteredTasks.length === 0 ? (
            <div className="no-tasks">
              <p>No tasks found.</p>
              <button className="add-task-btn" onClick={handleAddTask}>
                Create your first task
              </button>
            </div>
          ) : (
            filteredTasks.map((task, index) => (
              <div key={task.id} className="task-card" style={{animationDelay: `${index * 0.1}s`}}>
                <div className="task-header">
                  <div>
                    <div className="task-title">{task.User_Task}</div>
                    <div className="task-meta">
                      <span>Due: {formatDate(task.date_time)}</span>
                      <span>Priority: {task.priority}</span>
                      <span>Status: {task.status}</span>
                    </div>
                  </div>
                  <div className="task-actions">
                    <button className="action-btn edit-btn" onClick={() => handleEditTask(task)}>Edit</button>
                    <button className="action-btn delete-btn" onClick={() => handleDeleteTask(task.id)}>Delete</button>
                  </div>
                </div>
                {task.descri && (
                  <div className="task-description">{task.descri}</div>
                )}
              </div>
            ))
          )}
        </div>
      </main>

      {showTaskModal && (
        <TaskModal
          User_Task={editingTask}
          onSave={handleTaskSaved}
          onClose={() => setShowTaskModal(false)}
        />
      )}
    </div>
  );
};

export default Dashboard;
